param([Parameter(Mandatory)][string]$CandidateSnapshotId,[Parameter(Mandatory)][string]$BaselineSnapshotId,[Parameter(Mandatory)][string]$ExperimentId)
$ErrorActionPreference='Stop';Set-StrictMode -Version Latest
function Require([bool]$Condition,[string]$Message){if(!$Condition){throw $Message}};function Hash([string]$Path){(Get-FileHash -Algorithm SHA256 -LiteralPath $Path).Hash}
$repositoryRoot=(& git -C $PSScriptRoot rev-parse --show-toplevel).Trim();$candidateRoot=Join-Path $repositoryRoot "artifacts/performance/$CandidateSnapshotId";$baselineRoot=Join-Path $repositoryRoot "artifacts/performance/$BaselineSnapshotId";$experimentRoot=Join-Path $candidateRoot $ExperimentId;$outputPath=Join-Path $candidateRoot 'validation/display-provider-strict-verification.json';Require(!(Test-Path $outputPath))'Strict report exists.';$candidateManifest=@(Import-Csv (Join-Path $candidateRoot 'manifest.csv'));$baselineManifest=@(Import-Csv (Join-Path $baselineRoot 'manifest.csv'));foreach($record in $candidateManifest){Require((Hash (Join-Path $candidateRoot "source/$($record.Path)"))-ceq $record.SHA256)"Candidate source differs: $($record.Path)"};foreach($record in $baselineManifest){Require((Hash (Join-Path $baselineRoot "source/$($record.Path)"))-ceq $record.SHA256)"Baseline source differs: $($record.Path)"};$verifier=@($candidateManifest|Where-Object Path -CEQ 'scripts/performance/Verify-DisplayProviderSnapshot.ps1');Require($verifier.Count-eq 1 -and $verifier[0].SHA256-ceq(Hash $PSCommandPath))'Verifier differs.';$fixturePath='FancyWM.Tests/Utilities/Win32DisplayManagerSnapshotTest.cs';Require(@($candidateManifest|Where-Object Path -CEQ $fixturePath)[0].SHA256-ceq @($baselineManifest|Where-Object Path -CEQ $fixturePath)[0].SHA256)'A/B fixture differs.'
$rows=@(Import-Csv (Join-Path $experimentRoot 'measurements.csv'));$raw=@(Import-Csv (Join-Path $experimentRoot 'raw-counters.csv'));$processes=@(Import-Csv (Join-Path $experimentRoot 'process-times.csv'));$checks=@(Import-Csv (Join-Path $experimentRoot 'binary-checks.csv'));$provenance=Get-Content -Raw (Join-Path $experimentRoot 'provenance.json')|ConvertFrom-Json -DateKind String;Require($rows.Count-eq 210 -and $raw.Count-eq 210 -and $processes.Count-eq 10 -and $provenance.Verdict-ceq 'MEASUREMENT_CHECKS_PASS')'Evidence dimensions differ.';Require($provenance.MeasurementsSHA256-ceq(Hash (Join-Path $experimentRoot 'measurements.csv')) -and $provenance.RawCountersSHA256-ceq(Hash (Join-Path $experimentRoot 'raw-counters.csv')) -and $provenance.ProcessTimesSHA256-ceq(Hash (Join-Path $experimentRoot 'process-times.csv')) -and $provenance.BinaryChecksSHA256-ceq(Hash (Join-Path $experimentRoot 'binary-checks.csv')))'Evidence hash differs.';Require(@($checks|Where-Object{($_.Path-ceq 'WinMan.Windows.dll')-ne($_.CandidateSHA256-cne $_.BaselineSHA256)}).Count-eq 0 -and @($checks|Where-Object Path -CEQ 'WinMan.Windows.dll').Count-eq 1)'Binary delta differs.'
$values=[Collections.Generic.Dictionary[string,long]]::new([StringComparer]::Ordinal);foreach($row in $rows){$match=[regex]::Match($row.scenario,'; (?<count>1|10|50) displays;');Require($match.Success -and $row.experiment_id-ceq $ExperimentId -and $row.perf_id-ceq 'PERF-022' -and $row.variant-cin @('baseline','candidate'))'Row identity differs.';$pair=[int]$row.pair;$count=[int]$match.Groups['count'].Value;$value=[long]$row.value;Require($values.TryAdd("$pair/$($row.variant)/$count/$($row.metric)",$value))'Duplicate measurement key.'}
$allocationWins=0;$timingWins=0;foreach($pair in 1..5){foreach($count in @(1,10,50)){foreach($variant in @('baseline','candidate')){$prefix="$pair/$variant/$count";Require($values["$prefix/calls"]-eq 10000 -and $values["$prefix/returned-items"]-eq 10000*$count -and $values["$prefix/fresh-lists"]-eq 10000 -and $values["$prefix/timestamp-frequency"]-eq [Diagnostics.Stopwatch]::Frequency -and $values["$prefix/allocated-bytes"]-gt 0 -and $values["$prefix/elapsed-ticks"]-gt 0)'Semantic metrics differ.'};foreach($metric in @('calls','returned-items','fresh-lists','timestamp-frequency','checksum')){Require($values["$pair/baseline/$count/$metric"]-eq $values["$pair/candidate/$count/$metric"])"A/B semantics differ: $pair/$count/$metric"};if($values["$pair/candidate/$count/allocated-bytes"]-lt $values["$pair/baseline/$count/allocated-bytes"]){$allocationWins++};if($values["$pair/candidate/$count/elapsed-ticks"]-lt $values["$pair/baseline/$count/elapsed-ticks"]){$timingWins++}}};Require($allocationWins-eq 15)'Allocation claim failed.'
for($index=0;$index-lt 10;$index++){$pair=[int][Math]::Floor($index/2)+1;$first=if($pair%2){'baseline'}else{'candidate'};$variant=if($index%2-eq 0){$first}else{if($first-ceq 'baseline'){'candidate'}else{'baseline'}};Require([int]$processes[$index].Pair-eq $pair -and $processes[$index].Variant-ceq $variant -and [int]$processes[$index].ExitCode-eq 0)'Process order differs.';if($index-gt 0){Require([DateTimeOffset]::Parse($processes[$index].StartedUtc)-ge [DateTimeOffset]::Parse($processes[$index-1].FinishedUtc))'Processes overlap.'}}
[xml]$baselineTrx=Get-Content -Raw (Join-Path $baselineRoot 'validation/Release-provider-snapshot.trx');[xml]$candidateTrx=Get-Content -Raw (Join-Path $candidateRoot 'validation/Release-provider-snapshot.trx');$baselineAll=@($baselineTrx.SelectNodes("//*[local-name()='UnitTestResult']"));$candidateAll=@($candidateTrx.SelectNodes("//*[local-name()='UnitTestResult']"));$baselineLeaves=@($baselineAll|Where-Object{$_.SelectNodes("./*[local-name()='InnerResults']/*[local-name()='UnitTestResult']").Count-eq 0});$candidateLeaves=@($candidateAll|Where-Object{$_.SelectNodes("./*[local-name()='InnerResults']/*[local-name()='UnitTestResult']").Count-eq 0});Require($baselineLeaves.Count-eq 9 -and @($baselineLeaves|Where-Object outcome -CNE 'Passed').Count-eq 3 -and $candidateLeaves.Count-eq 9 -and @($candidateLeaves|Where-Object outcome -CNE 'Passed').Count-eq 0)'Red/green fixture differs.'
$report=[ordered]@{Verdict='ACCEPT';Accepted=$true;PerfId='PERF-022';CandidateSnapshotId=$CandidateSnapshotId;BaselineSnapshotId=$BaselineSnapshotId;ExperimentId=$ExperimentId;Rows=210;Pairs=5;Processes=10;AllocationWins=$allocationWins;TimingWins=$timingWins;TimingLosses=15-$timingWins;BaselineRed='6 pass / 3 allocation fail';CandidateGreen='9/9';NativeCalls=$false;MeasurementsSHA256=Hash (Join-Path $experimentRoot 'measurements.csv');RawCountersSHA256=Hash (Join-Path $experimentRoot 'raw-counters.csv');ProcessTimesSHA256=Hash (Join-Path $experimentRoot 'process-times.csv');BinaryChecksSHA256=Hash (Join-Path $experimentRoot 'binary-checks.csv');VerifierSHA256=Hash $PSCommandPath;CreatedUtc=[DateTimeOffset]::UtcNow.ToString('o')};$report|ConvertTo-Json -Depth 4|Set-Content $outputPath;$report|ConvertTo-Json -Depth 4
